import React, { useEffect, useState } from "react";
import { AlertTriangle } from "lucide-react";

// The AI reports are generated by a request that lives in this page: refreshing or closing the tab cancels it,
// and the person starts over. These tell them so while it runs, and give them a way forward if it fails.
// They render inside the dashboard, so they use its design tokens (components/dashboard/dashboard.css).

/** Asks the browser to confirm before the tab is closed or refreshed, for as long as `active` is true. */
export function useLeaveWarning(active: boolean) {
  useEffect(() => {
    if (!active) return;
    const warn = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = ""; // some browsers only show the prompt when this is set
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [active]);
}

export const GenerationNotice: React.FC<{ what: string }> = ({ what }) => {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div
      role="status"
      data-testid="generation-notice"
      className="flex items-start gap-4 rounded-2xl border border-[var(--d-accent-line)] bg-[var(--d-accent-soft)] px-5 py-4 text-left"
    >
      <span className="relative mt-1 grid h-5 w-5 shrink-0 place-items-center" aria-hidden="true">
        <span className="absolute inset-0 animate-ping rounded-full bg-[var(--d-accent)] opacity-25" />
        <span className="h-2 w-2 rounded-full bg-[var(--d-accent)]" />
      </span>
      <div className="min-w-0">
        <p className="text-[14px] font-medium">
          Generating your {what}
          <span className="d-mono ml-2 text-[12px] text-[var(--d-accent)]">{seconds}s</span>
        </p>
        <p className="d-body mt-1 text-[13px]">
          This can take up to a minute. Keep this tab open and don't refresh or close the page until it finishes.
        </p>
      </div>
    </div>
  );
};

export const GenerationFailed: React.FC<{ what: string; onRetry: () => void }> = ({ what, onRetry }) => (
  <div
    data-testid="generation-failed"
    className="flex min-h-[320px] flex-col items-center justify-center p-10 text-center"
  >
    <span className="mb-5 grid h-12 w-12 place-items-center rounded-xl border border-[var(--d-line2)] bg-[var(--d-s2)] text-[var(--d-warn)]">
      <AlertTriangle className="h-5 w-5" strokeWidth={1.5} />
    </span>
    <h3 className="d-h2">We couldn't generate your {what}</h3>
    <p className="d-body mx-auto mt-2 max-w-sm">Your scan is safe. This usually works on a second try. Keep this tab open while it generates.</p>
    <button type="button" onClick={onRetry} className="d-btn d-btn-primary mt-6">
      <span>Try again</span>
      <span className="d-btn-dot">
        <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M13 8a5 5 0 1 1-1.6-3.7M13 3v3h-3" />
        </svg>
      </span>
    </button>
  </div>
);
